/* Advanced2 — account isolation, inherited ceilings and explicit grant paths. */
(function(){
 const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x));
 const ROOT='r-shop',W='ou-shop-00000001',PROD='ou-shop-00000002',SEC='ou-shop-00000003',SAND='ou-shop-00000004',MGMT='111111111111',DEV='444444444444',AUDIT='666666666666',SERVICE='config-multiaccountsetup.amazonaws.com';
 const canonical=(v,k='')=>{if(['Action','NotAction','Resource','NotResource','aws:RequestedRegion','s3:LocationConstraint'].includes(k)&&(typeof v==='string'||Array.isArray(v)&&v.every(x=>typeof x==='string')))return (Array.isArray(v)?v:[v]).slice().sort();if(Array.isArray(v)){const a=v.map(x=>canonical(x));if(a.every(x=>x&&typeof x.Sid==='string'))a.sort((a,b)=>a.Sid.localeCompare(b.Sid));return a;}return v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k],k)])):v;};
 const same=(a,b)=>JSON.stringify(canonical(a))===JSON.stringify(canonical(b));
 const FULL={Version:'2012-10-17',Statement:[{Effect:'Allow',Action:'*',Resource:'*'}]};
 const REGION={Version:'2012-10-17',Statement:[{Sid:'ScopedRegionalAPIs',Effect:'Deny',Action:['ec2:*','rds:*','s3:CreateBucket'],Resource:'*',Condition:{StringNotEquals:{'aws:RequestedRegion':'ap-south-1'}}},{Sid:'BucketLocation',Effect:'Deny',Action:'s3:CreateBucket',Resource:'*',Condition:{StringNotEquals:{'s3:LocationConstraint':'ap-south-1'}}}]};
 const PROTECT={Version:'2012-10-17',Statement:[{Sid:'ProtectTrail',Effect:'Deny',Action:['cloudtrail:StopLogging','cloudtrail:DeleteTrail'],Resource:'*'}]};
 const IDENTITY={Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:CreateBucket','s3:PutObject','cloudtrail:StopLogging'],Resource:'*'}]};
 const files={'region.json':{desc:'Reviewed scoped EC2/RDS/S3CreateBucket endpoint and bucket-location ceiling; global services not blanket-denied',content:JSON.stringify(REGION,null,2)},'audit.json':{desc:'Reviewed member-identity StopLogging/DeleteTrail ceiling; SLR/management exceptions still exist',content:JSON.stringify(PROTECT,null,2)},'identity.json':{desc:'Existing reviewed sandbox role grant; an SCP does not create this grant',content:JSON.stringify(IDENTITY,null,2)}};
 const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
 function seed(sandbox=false,broken=false){
  const units=[{id:W,name:'Workloads',parentId:ROOT,fixtureId:'original-workloads'},{id:PROD,name:'Production',parentId:W,fixtureId:'original-prod'},{id:SEC,name:'Security',parentId:ROOT,fixtureId:'original-security'},...(sandbox?[{id:SAND,name:'Sandbox',parentId:W,fixtureId:'original-sandbox'}]:[])];
  const accounts=[[MGMT,'management',ROOT],['222222222222','prod-web',PROD],['333333333333','prod-data',PROD],[DEV,'dev-sandbox',sandbox?SAND:PROD],['555555555555','log-archive',SEC],[AUDIT,'audit',SEC]].map(([id,name,parentId])=>({id,name,parentId,state:'ACTIVE',fixtureId:'original-'+id,email:name+'@example.invalid'}));
  const region=clone(REGION);if(broken)region.Statement[0].Condition={StringEquals:{'aws:RequestedRegion':'ap-south-1'}};
  return {region:'us-east-1',callerIdentity:{Account:MGMT,Arn:`arn:aws:iam::${MGMT}:role/org-operator`,UserId:'TRAINING'},organization:{id:'o-shop123456',managementAccountId:MGMT,rootId:ROOT,email:'org-operator@example.invalid',featureSet:'ALL'},orgPolicyTypes:['SERVICE_CONTROL_POLICY'],orgAccounts:accounts,orgUnits:units,orgOuSequence:sandbox?4:3,orgRevision:1,orgServiceAccess:sandbox?[SERVICE]:[],orgDelegates:sandbox?[{accountId:AUDIT,service:SERVICE,id:'original-config-delegation'}]:[],orgRoleIdentityPolicy:clone(IDENTITY),
   scps:[{id:'p-FullAWSAccess',name:'FullAWSAccess',description:'AWS managed Allow baseline',awsManaged:true,revision:1,document:clone(FULL),targets:[ROOT,...units.map(u=>u.id),...accounts.map(a=>a.id)].filter(id=>!broken||id!==W)},{id:'p-region01',name:'SandboxRegion',description:'Reviewed scoped region/location ceiling',awsManaged:false,revision:1,document:region,targets:sandbox?[SAND]:[]},{id:'p-notrail1',name:'ProtectAuditTrail',description:'Reviewed trail protection',awsManaged:false,revision:1,document:clone(PROTECT),targets:sandbox?[SAND]:[]},...(broken?[{id:'p-pathdeny',name:'IncompleteAllowList',description:'Deny-only replacement leaves no Allow',awsManaged:false,revision:1,document:{Version:'2012-10-17',Statement:[{Effect:'Deny',Action:'s3:DeleteBucket',Resource:'*'}]},targets:[W]}]:[])],
   queues:[{name:'prod-orders',queueId:'original-prod-orders',arn:'arn:aws:sqs:ap-south-1:222222222222:prod-orders',url:'https://sqs.ap-south-1.amazonaws.com/222222222222/prod-orders',ownerAccount:'222222222222',isFifo:false,visibilityTimeout:120,messages:[{messageId:'original-work101',body:'{"orderId":"accepted101","total":499}',visibleAt:0,sentAt:0,receiveCount:0}]}],rds:[{id:'prod-orders',resourceId:'db-original-org-orders',name:'prod-orders',engine:'postgres',class:'db.t3.medium',state:'available',multiAZ:true,backupRetention:7,encrypted:true,publicAccess:false,deletionProtection:true,storage:100,dataFixture:[{orderId:'accepted101',total:499}]}]
  };
 }
 const initial=seed(),sandbox=s=>s.account.orgUnits.find(u=>u.name==='Sandbox'&&u.parentId===W);
 function preserved(s){const a=s.account;return same(a.organization,initial.organization)&&same(a.orgPolicyTypes,['SERVICE_CONTROL_POLICY'])&&a.orgAccounts.length===6&&initial.orgAccounts.every(orig=>{const c=a.orgAccounts.find(c=>c.id===orig.id);return !!c&&c.fixtureId===orig.fixtureId&&c.name===orig.name&&c.state==='ACTIVE'&&(c.id===DEV||c.parentId===orig.parentId);})&&initial.orgUnits.every(u=>same(a.orgUnits.find(x=>x.id===u.id),u))&&same(a.orgRoleIdentityPolicy,IDENTITY)&&a.queues.length===1&&a.queues[0].queueId==='original-prod-orders'&&a.queues[0].messages.length===1&&a.queues[0].messages[0].messageId==='original-work101'&&a.queues[0].messages[0].body===initial.queues[0].messages[0].body&&a.rds.length===1&&same(a.rds[0],initial.rds[0]);}
 function baseline(s,interview=false){const a=s.account,u=sandbox(s),full=a.scps.find(p=>p.id==='p-FullAWSAccess'),ids=[ROOT,W,PROD,SEC,...initial.orgAccounts.map(c=>c.id),...(u?[u.id]:[])].sort();if(a.scps.length!==(interview?4:3)||!full||!full.awsManaged||!same(full.document,FULL)||!same((full.targets||[]).slice().sort(),ids))return false;if(interview){const p=a.scps.find(p=>p.id==='p-pathdeny');return !!p&&same(p.targets,[W])&&same(p.document,{Version:'2012-10-17',Statement:[{Effect:'Deny',Action:'s3:DeleteBucket',Resource:'*'}]});}return true;}
 function requests(a,identity='allow',boundary='none',resourcePolicy='none'){
  const request=(action,region,location,resource='*',rp='none')=>AG.orgRequestDecision(a,{accountId:DEV,principalType:'role',principalArn:`arn:aws:iam::${DEV}:role/sandbox-dev`,action,resource,region,location,identity,boundary,resourcePolicy:rp});
  return [request('s3:CreateBucket','ap-south-1','ap-south-1','arn:aws:s3:::training-new'),request('s3:CreateBucket','eu-west-1','ap-south-1','arn:aws:s3:::training-new'),request('s3:CreateBucket','ap-south-1','eu-west-1','arn:aws:s3:::training-new'),request('cloudtrail:StopLogging','ap-south-1'),request('s3:PutObject','ap-south-1',undefined,'arn:aws:s3:::sandbox-data/training.txt',resourcePolicy)];
 }
 function guardrails(s){const a=s.account,u=sandbox(s),p=a.scps.find(p=>p.id==='p-region01'),t=a.scps.find(p=>p.id==='p-notrail1');if(!u||a.orgUnits.length!==4||a.orgAccounts.find(c=>c.id===DEV)?.parentId!==u.id||!p||!t||!same(p.document,REGION)||!same(t.document,PROTECT)||!same(p.targets,[u.id])||!same(t.targets,[u.id]))return false;const r=requests(a);return r[0].allowed&&!r[1].allowed&&!r[2].allowed&&!r[3].allowed&&r[4].allowed;}
 function delegated(s){const a=s.account;return a.orgServiceAccess.length===1&&a.orgServiceAccess[0]===SERVICE&&a.orgDelegates.length===1&&a.orgDelegates[0].accountId===AUDIT&&a.orgDelegates[0].service===SERVICE&&(a.orgDelegationReads||[]).some(r=>r.revision===a.orgRevision&&r.service===SERVICE&&same(r.ids,[AUDIT]));}
 const solution=[`aws organizations create-organizational-unit --parent-id ${W} --name Sandbox`,`aws organizations move-account --account-id ${DEV} --source-parent-id ${PROD} --destination-parent-id ${SAND}`,`aws organizations attach-policy --policy-id p-region01 --target-id ${SAND}`,`aws organizations attach-policy --policy-id p-notrail1 --target-id ${SAND}`,`aws organizations enable-aws-service-access --service-principal ${SERVICE}`,`aws organizations register-delegated-administrator --account-id ${AUDIT} --service-principal ${SERVICE}`,`aws organizations list-delegated-administrators --service-principal ${SERVICE}`];
 const tasks=[{text:'Original accounts/Production+Security OUs, IAM grant and production order DB/queue preserved',check:s=>preserved(s)&&baseline(s)},{text:'Sandbox under Workloads, dev account moved, reviewed scoped policies attached and effective request contracts correct',check:guardrails},{text:'Config rules/conformance-pack trusted access+audit delegation registered and current registry read',check:delegated}];
 const isolution=[`aws organizations attach-policy --policy-id p-FullAWSAccess --target-id ${W}`,'aws organizations update-policy --policy-id p-region01 --content file://region.json','aws organizations describe-policy --policy-id p-region01'];
 const itasks=[{text:'Original account/tree/production work and IAM grant preserved',check:s=>preserved(s)&&baseline(s,true)&&sandbox(s)?.id===SAND&&sandbox(s)?.fixtureId==='original-sandbox'},{text:'Reviewed effective Sandbox ceilings; no ancestor Allow gap or reversed region condition',check:guardrails},{text:'Original service-specific delegation/access retained; current corrected region policy content read',check:s=>{const a=s.account,p=a.scps.find(p=>p.id==='p-region01');return !!p&&same(a.orgServiceAccess,[SERVICE])&&same(a.orgDelegates,[{accountId:AUDIT,service:SERVICE,id:'original-config-delegation'}])&&(a.orgPolicyReads||[]).some(r=>r.id===p.id&&r.revision===p.revision&&same(r.document,p.document));}}];
 function board(k){const a=seed(true),full=a.scps[0];for(const [id,allow]of [[ROOT,k.root],[W,k.ou],[DEV,k.account]])if(!allow){full.targets=full.targets.filter(t=>t!==id);a.scps.push({id:'p-gap-'+id,targets:[id],document:{Version:'2012-10-17',Statement:[{Effect:'Deny',Action:'s3:DeleteBucket',Resource:'*'}]}});}if(k.guard===0)a.scps[1].targets=[];if(k.guard===2)a.scps[1].document.Statement[0].Condition={StringEquals:{'aws:RequestedRegion':'ap-south-1'}};const r=requests(a,['none','allow','deny'][k.iam],['none','allow','deny'][k.boundary],['none','allowRoleArn','deny'][k.resource]),ok=r[0].allowed&&!r[1].allowed&&!r[2].allowed&&!r[3].allowed&&r[4].allowed;return {r,ok};}
 AG.registerLevels('advanced',[{
  id:'orgs',icon:'🏢',title:'Organizations — boundaries, grants aur guardrails',badge:'Landing Zone Lord',
  objectives:['Account/OU design se blast radius aur ownership scope samajhna','Root→OU→account SCP ceilings aur IAM/resource grant path evaluate karna','Identity Center, Control Tower, RAM aur service delegation choose karna','Current policy types/billing/tagging boundaries ke saath safe canary governance configure karna'],
  hook:{when:'ShopKaro course story — fictional',title:'40 engineers, shared access aur wrong-workspace destroy',text:'Ravi ne dev samajhkar Terraform destroy chalaya; broad credentials ne prod queue delete kar di. Tags ne separate ownership provide nahi ki. Neha wants account isolation, scoped human access and an exception path; a huge AdministratorAccess policy is not a recovery plan.',mission:'Build a small Sandbox boundary, move only the intended dev account, attach reviewed ceilings and register one service-specific audit delegate. Preserve production work. Moto metadata is not real AWS enforcement proof.'},
  steps:[
   {q:'Account boundary strong hai; complete immunity kyun nahi?',analogy:'Separate bank lockers isolate keys and records. A master key shared with every team can still cross the separation.',body:'<p>AWS accounts provide strong resource/identity/billing and many account/Region quota boundaries. Put production and nonproduction under explicit ownership and limit cross-account trust. Account isolation does not protect against credentials or roles authorized across accounts, shared dependencies or management compromise.</p>',points:['Course story:40 engineers move from shared broad access toward management, Security(log-archive/audit), Infrastructure and Workloads(Production/Dev/Sandbox). Group OUs by shared policy requirements, not an org-chart copy for its own sake.','Galti jo sab karte hain:tags ko authorization boundary samajhna, or assume every quota is uniquely per-account with no Region/service exceptions. Tags support allocation/ABAC only where the actual policy/service supports the intended condition.','Hands-on:main mission moves only dev-sandbox. Expected:prod-web/prod-data and original orders DB/queue remain unchanged; moving the production account into Sandbox is not a valid fix.'],asli:'Use the management account for tasks that require it, keep workloads elsewhere, protect root/break-glass access and review cross-account trust. SCPs do not constrain management identities.'},
   {q:'SCP path mein Allow aur Deny ka exact rule kya hai?',analogy:'Building, floor aur lab each must permit entry. Any applicable explicit prohibition blocks entry; a floor pass cannot override the building ceiling.',body:'<p>SCPs limit member identities, including member root and delegated-administrator accounts; they do not grant access. Evaluate an applicable Allow at root, every OU in the path and the target account, then all applicable Denies. At one node multiple policies can contribute Allows; across nodes every level must allow. Any applicable explicit Deny wins.</p>',points:['FullAWSAccess baseline is automatically attached when SCPs are enabled to preserve broad ceilings. Removing FullAWSAccess does not inevitably lock everything if another applicable Allow remains; leaving no Allow at a required path level blocks the request.','Management identities and service-linked roles are exempt from SCP restrictions; exemption does not grant arbitrary IAM/service access. External principals accessing a member resource are not limited by the resource owner account’s SCP simply because the resource lives there. RCPs address supported resource ceilings separately.','Hands-on:dry run/board remove one ancestor Allow while IAM remains admin. Expected:denied at the missing path layer. Review supported global-service exceptions before any broad Region rule.'],asli:'As of the 2025 full IAM-language expansion, SCP Allow can use conditions/resources/NotAction; NotResource and broader Action wildcards also exist. The local evaluator declares a narrower supported subset; older blanket syntax restrictions are stale.'},
   {q:'SCP grants nahi deta; IAM/resource/boundary interaction kaise padhein?',analogy:'Building ceiling permits entry, but a valid invitation is still required. A room-specific invitation can be another grant; explicit prohibitions still matter.',body:'<p>Identity policies grant actions; permissions boundaries and session policies can limit the applicable grant path. Resource-based grants differ by principal type. In the same-account role-ARN case, a resource policy can grant object access without an identity Allow, while an implicit boundary/session-policy denial still limits that role grant. Direct user/session ARN and wildcard Principal+PrincipalArn paths have different exceptions.</p>',points:['The board models a same-account role with optional existing-bucket role-ARN grant for s3:PutObject, an identity grant/explicit Deny, a boundary and SCPs. It excludes direct user/session ARN grants, cross-account trust, session policies, RCPs and a full IAM engine.','CreateBucket cannot receive permission from a policy on a future nonexistent bucket. The optional resource policy affects only the existing PutObject scenario. Explicit identity/resource Deny and the applicable SCP ceiling still block access.','Hands-on:remove IAM Allow but select role-ARN resource Allow. Expected:existing PutObject can pass if boundary/SCP permit; CreateBucket still fails. Restore IAM Allow to satisfy both contracts.'],asli:'Do not apply the simplified SCP∩IAM formula to every resource-policy/principal case. Name the principal, resource owner, grant path and applicable Denies.'},
   {q:'Workforce access centralize karein, service roles ko kaise distinguish karein?',analogy:'One employee badge portal issues the right building-specific passes; it does not make every employee a building owner.',body:'<p>IAM Identity Center connects workforce users/groups and supported applications/accounts. One supported organization-instance workflow uses permission sets to provision account roles and assign groups. Account instances serve isolated supported applications; organization instances enable multi-account AWS access. Current account-access-manager workflows can also centralize existing roles. Customer app login is a different Cognito-style requirement.</p>',points:['Use temporary scoped account sessions, MFA/IdP controls, reviewed group assignments and offboarding. An Identity Center portal does not override SCPs, boundaries or resource authorization. Machine workloads use appropriate IAM/service roles rather than a shared human access key.','Delegated administrator is service-specific authority in a member account, not management ownership or an SCP exemption. Config rules/conformance packs use config-multiaccountsetup.amazonaws.com; aggregation has a separate config.amazonaws.com integration. GuardDuty/SecurityHub have service-specific setup workflows.','Hands-on:main registers audit for the documented Config rules/conformance-pack integration after enabling trusted access. Expected registry metadata only; no Config rules/recorders or Identity Center service is deployed.'],asli:'Check each service’s supported admin API, trusted-access prerequisites and required runtime configuration. Organizations registration alone does not configure the whole service.'},
   {q:'Control Tower ka baseline kaunse path ko govern karta hai?',analogy:'A housing developer provides standard wiring, inspection rules and a repeatable handover process. A standard template does not guarantee every later renovation used that process.',body:'<p>Control Tower builds/governs a landing zone and Account Factory supports repeatable account provisioning with a baseline. Review Region/control coverage, enrollment and drift. Current preventive controls use SCPs/RCPs/declarative policies; detective controls use AWS Config rules; proactive controls use CloudFormation Hooks before supported create/update provisioning paths.</p>',points:['Proactive CloudFormation controls do not imply every direct SDK/API or Terraform AWS-provider request was checked. Managing Control Tower controls with Terraform is separate from every Terraform-provisioned resource passing a CloudFormation hook.','Galti jo sab karte hain:one-click landing zone ko all compliance/risk work complete samajhna. Ownership, identity, networks, service coverage, exceptions and actual control results still need evidence.','Hands-on:bins distinguish a grant, an authorization ceiling and a baseline/detection/provisioning control. Expected:Account Factory creates the chosen account baseline; it is not a permission grant.'],asli:'Canary a control on an isolated OU/account with a rollback/exception owner. Do not attach an untested broad Deny at the organization root.'},
   {q:'Central logging ko tamper-resistant kaise banayein?',analogy:'CCTV recording ko separate locked archive mein store karo. Archive key sab visitors ko dena ya retention policy ignore karna separation ka benefit erase karta hai.',body:'<p>An organization trail can centralize selected member activity to a separate log-archive account. Review destination/KMS ownership and policies, delegated service authority, log delivery/validation and required retention. SCP protections for member identities complement isolation; they do not constrain management identities or service-linked roles.</p>',points:['Object Lock mode, retention/legal hold and authorized principals matter. Governance mode can be bypassed by authorized bypass permissions; compliance mode has different retention behavior. A trail destination alone is not a universal tamper-proof guarantee.','RequestedRegion controls a request endpoint, not all downstream data placement. Course policy scopes EC2/RDS/S3CreateBucket endpoints to Mumbai and independently checks S3LocationConstraint. Global services need deliberate reviewed treatment; this example is not a whole data-residency policy.','Hands-on:triage inspect OU policies, actual parent path and the requested endpoint/location. Expected:identify a current ceiling or missing Allow, rather than repeatedly widening IAM admin access.'],asli:'Verify actual delivered logs/digests, integrity validation, access/retention and response ownership. Local org/SCP metadata cannot prove those production outcomes.'},
   {q:'RAM, billing aur delegation shared ownership bana dete hain?',analogy:'Shared kitchen booking lets another team use equipment; ownership, operating rules and the invoice agreement still exist.',body:'<p>AWS RAM shares supported resources such as subnets/TGW with permitted accounts/OUs/principals. The owner retains ownership; consuming-account grants and ceilings still apply. Supported resource types, regional scope and invitation/organization-sharing setup differ. Resource sharing is not a transfer of account ownership.</p>',points:['Consolidated billing aggregates eligible usage/discounts and account cost data; one bill can depend on seller-of-record boundaries. Eligible RI/Savings Plans benefits follow current billing preferences, including open/prioritized/restricted group sharing. Purchasing-account eligibility and sharing settings matter; no universal percentage saving.','Galti jo sab karte hain:discount sharing ko running capacity reservation, duplicated Free Tier, unlimited shared quotas or permission sharing samajhna. Billing and authorization have different contracts.','Hands-on:compare shared subnet, cross-account role, delegated Config admin and billing preference. Expected:pick RAM for supported resource sharing, IAM/Identity Center for access, service delegation for administration, billing preferences for eligible benefits.'],asli:'Centralization changes who operates and pays; keep explicit owner, permission, failure and cost-allocation boundaries.'},
   {q:'Tag, backup, RCP aur declarative policies ko SCP kyun na samjhein?',analogy:'Expense labels, backup schedule, locker access ceiling and building-wide safety configuration are different rules with different enforcement points.',body:'<p>Tag policies have basic key/value/case consistency plus current Required-tag-key/reporting/IaC workflows. Basic consistency enforcement does not block missing tags. Required-key reporting/IaC validation has specific tooling/resource visibility limitations; supported request-tag SCP/IAM conditions can guard selected create APIs. Backup policies centrally define supported backup configuration; jobs, selections, copies and restores need actual evidence.</p>',points:['RCPs are permission ceilings for supported resources in member accounts, including access by external principals; they do not grant access, govern management-account resources or calls by service-linked roles. Supported service list evolves; S3 is a current example, not a claim that every service supports RCPs.','Declarative policies enforce supported service control-plane settings and differ from principal/API authorization ceilings. Their supported settings can govern service-linked-role behavior too. Do not apply SCP inheritance/evaluation mechanically to tag/backup/declarative policy types.','Hands-on:lab22 checks actual organization attachment/delegation and a forbidden member request. Expected:Moto accepts the forbidden bucket despite Deny; the bounded evaluator teaches the documented logic. No tag/RCP/backup/declarative runtime enforcement is claimed.'],asli:'Choose the policy from the control objective, supported resource/API and current enforcement/reporting mode. Verify coverage and exceptions before rollout.'}
  ],
  myth:[{myth:'Accounts guarantee that broad cross-account credentials cannot touch production.',sach:'Accounts isolate resources; trust/permissions and shared credentials can cross that boundary. Limit access and preserve recovery evidence.'},{myth:'FullAWSAccess removal always locks the entire organization.',sach:'A request needs an applicable Allow at every path level. A reviewed replacement can preserve permission; missing Allow or explicit Deny blocks it.'},{myth:'SCP, resource policy and IAM grants always form one simple intersection.',sach:'SCP ceilings and explicit Denies remain, but the actual grant/implicit-deny rules depend on principal/resource ownership and grant path.'},{myth:'Attached metadata or a central trail proves production governance.',sach:'Test actual supported enforcement, delivery, retention, identity and exceptions. Moto and service-specific prerequisites have explicit gaps.'}],
  playbook:{title:'Boundary → grant → ceiling → verified rollout',use:['Separate production/nonproduction ownership and constrain cross-account trust.','Use member OU guardrails after canary tests, while retaining required Allow paths.','Delegate service operations narrowly; centralize workforce access and supported resource sharing with distinct tools.'],avoid:['Untested root-wide Deny, blocking every global service or assuming Region equals all data placement.','Replacing IAM grants with SCP Allow or assuming management/SLRs are restricted by SCP.','Declaring compliance from metadata, discounts or a policy attachment name.'],how:['Identify caller/principal type, resource owner, action and request context.','Inspect root→eachOU→account Allows and applicable explicit Denies.','Identify identity/resource grant path and boundary/session/RCP scope.','Roll out to an isolated canary, verify real outcomes, document owner/exception/rollback.'],redflags:['Admin denied:missing ancestor Allow, inherited Deny, boundary or resource policy, not just a typo.','Tag value consistency is called universal missing-tag enforcement.','Service delegation is registered but trusted access/runtime setup is missing.'],rule:'Which boundary grants access, which ceiling limits the request, and which actual service test proves the promised control?'},
  exam:[{cue:'Grant versus ceiling',pick:'IAM/resource grant path; SCP never grants'},{cue:'Inherited member permission',pick:'Allow at root/everyOU/account; any applicable Deny wins'},{cue:'Management / service-linked role',pick:'SCP exemption; not unlimited permissions'},{cue:'Workforce multi-account portal',pick:'Identity Center organization instance + reviewed assignments'},{cue:'New account baseline',pick:'Control Tower Account Factory; coverage/drift still reviewed'},{cue:'Share supported subnet/TGW',pick:'RAM; owner retains resource and consumer permissions apply'},{cue:'Member service administrator',pick:'Service-specific delegation/prerequisites; still SCP-bound'},{cue:'S3Region restriction',pick:'RequestedRegion endpoint plus relevant LocationConstraint review'},{cue:'Tag/RCP/declarative objective',pick:'Different supported coverage and enforcement semantics'}],
  lesson:['<h3>Kab kya — control picker</h3><div class="tbl-wrap"><table class="review-table"><tr><th>Objective</th><th>Candidate</th><th>Boundary</th></tr><tr><td>Member identity ceiling</td><td>SCP</td><td>No grant; management/SLR exceptions</td></tr><tr><td>Grant workforce account access</td><td>Identity Center/IAM role</td><td>Assignments/trust/ceilings still apply</td></tr><tr><td>Standard account baseline</td><td>Account Factory</td><td>Enrollment/control coverage/drift</td></tr><tr><td>Supported resource sharing</td><td>RAM</td><td>Owner and consumer permissions remain</td></tr><tr><td>Member resource ceiling</td><td>RCP</td><td>Supported resources/principals; no grant</td></tr><tr><td>Desired service configuration</td><td>Declarative policy</td><td>Supported settings/control-plane scope</td></tr><tr><td>Labels / backup plans</td><td>Tag / backup policy</td><td>Mode/visibility/jobs/restore evidence</td></tr></table></div><p>Phone par table sideways swipe karo.</p><p><b>Decision tree:</b> Need a grant? Workforce→Identity Center/IAM; supported shared resource→RAM plus permissions. Need a ceiling? Member identity→SCP; supported member resource→RCP. Need a service baseline? Control Tower/declarative settings. Need tagging/backup configuration? Corresponding policy plus current coverage and actual verification.</p>'],
  stages:[
   {type:'dryrun',title:'🧪 One request, several independent decisions',intro:'Fictional Sandbox role request. Next click karo; panels show the applicable ceiling and grant path, not live AWS authorization.',lesson:'Root/every OU/account ceilings, explicit Denies, principal type and the actual grant path matter. This walkthrough excludes full IAM/session/RCP evaluation.',nodes:[N('iam',150,150,{label:'Root ceiling'}),N('org',470,150,{label:'OU ceilings'}),N('account',790,150,{label:'Member role'}),N('s3',790,420,{label:'Existing object'}),N('iam#grant',470,420,{label:'Grant / boundary'})],edges:[{from:'iam',to:'org'},{from:'org',to:'account'},{from:'account',to:'s3'},{from:'s3',to:'iam#grant'}],panels:[{id:'ceiling',title:'SCP path / principal scope'},{id:'grant',title:'Grant / boundary / request context'}],steps:[
    {say:'The member role requests CreateBucket at the Mumbai endpoint with Mumbai LocationConstraint. Root FullAWSAccess allows the ceiling; an IAM grant is still separate.',panels:{ceiling:['Root Allow found','No permission granted by the SCP'],grant:['Identity policy must allow this create request','A future bucket has no bucket-policy grant']}},
    {say:'Workloads contains only a Deny for DeleteBucket and no applicable Allow. Sandbox/account have FullAWSAccess; the role has AdministratorAccess.',panels:{ceiling:['Workloads:path Allow missing','Child Allow cannot widen ancestor ceiling'],grant:['AdministratorAccess cannot fix an SCP path gap']},ask:Q('What should the permission decision be for the stated missing-ancestor-Allow case?', 'Denied at Workloads despite child FullAWSAccess and IAM admin; restore an appropriate Allow path after review',['Allowed because the target account has FullAWSAccess and a child policy always overrides every ancestor policy','Allowed because AdministratorAccess is an identity grant that automatically disables inherited organization ceilings','Denied only if the role is in the management account because management identities are the identities restricted by SCPs'],0,'Every required path level must allow. A child or IAM admin cannot widen an ancestor ceiling; management identities are exempt from SCPs rather than the only restricted identities.')},
    {say:'Restore the reviewed Allow path. A separate request is PutObject to an existing same-account bucket. The bucket policy grants to the role ARN; IAM has no Allow, and the role boundary permits the action.',panels:{ceiling:['All path levels allow; no explicit Deny'],grant:['Existing role-ARN resource grant can supply PutObject permission','Boundary still limits this role-ARN grant']},ask:Q('What follows for this same-account role-ARN object grant path?', 'PutObject can be allowed without identity Allow when the resource grant, boundary and applicable ceilings permit',['PutObject must be denied because resource-based policies are never grants and can only remove IAM permissions','The resource Allow overrides every SCP Deny because an object owner can remove organization ceilings for member roles','The resource grant also permits CreateBucket before any bucket exists because all S3 permissions share one future policy'],1,'A same-account role-ARN resource grant is a real grant, limited by applicable boundary/ceilings. It cannot override SCP Deny or grant creation through a policy on a nonexistent bucket; other principal types have different rules.')},
    {say:'Now a scoped policy denies CreateBucket outside the Mumbai endpoint or with a non-Mumbai LocationConstraint. An allowed endpoint alone does not universally establish data residency.',panels:{ceiling:['Reviewed service/action scope','Global services not blanket-denied'],grant:['Endpoint Region and relevant destination context are distinct','Check the actual service API semantics']}},
    {say:'The audit account becomes Config delegated administrator. The account is still a member; its human/service roles remain SCP-bound except service-linked-role behavior.',panels:{ceiling:['Delegation does not exempt the member account','Management/SLR SCP exemptions are distinct'],grant:['Trusted access+service-specific registration metadata','Config runtime setup still separate']},ask:Q('Which account/principal claim is correct after service delegation?', 'Delegated member identities remain SCP-bound; management identities and service-linked roles have SCP exemptions',['The audit account becomes the management owner and is automatically exempt from every existing SCP and IAM boundary','A delegated admin grants every user in all member accounts new IAM permissions because registration replaces identity policy','All service roles are exempt because service-linked roles and ordinary application/service execution roles are interchangeable'],2,'Delegation is service-specific and does not change account ownership or grant every identity access. Management/SLR exceptions are specific; ordinary execution roles are not automatically service-linked roles.')},
    {say:'Read the current parent path, reviewed policy content and service registry. Local configuration/evaluator contracts can be ready; actual AWS enforcement and service runtime need a canary.',panels:{ceiling:['Original production accounts/work preserved','Current tree/policies, not command-history keywords'],grant:['Moto forbidden-region request is accepted despite SCP','No production enforcement certificate claimed']}}
   ]},
   {type:'flowlab',title:'🎛️ Permission calculator — declared role path',goal:'Allow Mumbai/Mumbai CreateBucket and existing Mumbai PutObject; deny EU endpoint create, Mumbai endpoint/EU location create and StopLogging. Start:Root/OU/account Full, reviewed Region guard, IAM Allow, boundary None, resource None.',scenario:'Bounded same-account member role. Three ceiling knobs choose Full Allow versus a legal Deny-only baseline that leaves the requested Allow missing. Region guard scopes EC2/RDS/S3CreateBucket endpoints plus S3LocationConstraint; audit StopLogging Deny is already attached. Optional resource policy applies only to existing PutObject and grants to the role ARN, not a user/session ARN. Identity/resource explicit Deny wins; role boundary still limits that role-ARN grant. No cross-account/session-policy/RCP/full IAM evaluation or live AWS call.',knobs:[{id:'root',label:'Root path Allow',min:0,max:1,step:1,value:1,labels:{0:'Allow missing',1:'Full Allow'}},{id:'ou',label:'Workloads OU Allow',min:0,max:1,step:1,value:0,labels:{0:'Allow missing',1:'Full Allow'}},{id:'account',label:'Target account Allow',min:0,max:1,step:1,value:1,labels:{0:'Allow missing',1:'Full Allow'}},{id:'guard',label:'Region/location policy',min:0,max:2,step:1,value:2,labels:{0:'Not attached',1:'Reviewed NotEquals',2:'Wrong Equals'}},{id:'iam',label:'Role identity policy',min:0,max:2,step:1,value:1,labels:{0:'No grant',1:'Allow',2:'Explicit Deny'}},{id:'boundary',label:'Role permissions boundary',min:0,max:2,step:1,value:0,labels:{0:'None',1:'Allows request',2:'Does not allow'}},{id:'resource',label:'Existing object resource policy',min:0,max:2,step:1,value:0,labels:{0:'None',1:'Role-ARN Allow',2:'Explicit Deny'}}],model:k=>{const b=board(k),labels=['Create:Mumbai endpoint+location','Create:EU endpoint,Mumbai location','Create:Mumbai endpoint,EU location','StopLogging:Mumbai','PutObject:existing Mumbai object'];return {readouts:b.r.map((r,i)=>({label:labels[i],value:(r.allowed?'Allowed':'Denied')+' • '+r.layer})),verdict:{ok:b.ok,text:b.ok?'All five declared role/request contracts fit. Real AWS enforcement and other principal/grant paths need separate tests.':'Inspect each deciding layer; keep intended access while blocking wrong endpoint/location and audit tampering.'}};},check:k=>board(k).ok,lesson:'SCP Allow is a ceiling, not a grant. Root/OU/account path gaps block the member. A role-ARN resource Allow can grant existing PutObject without IAM Allow if boundary/ceilings permit; it cannot grant CreateBucket through a future bucket policy. Explicit Denies remain. This is a bounded documented path, not a universal IAM formula.'},
   {type:'bins',title:'Grant, ceiling, dono ya service baseline?',instructions:'Choose the primary mechanism required by the stated objective. Exemptions, supported APIs and service setup still apply.',bins:[{id:'ceiling',label:'Authorization ceiling'},{id:'grant',label:'Grant / access'},{id:'both',label:'Grant + ceiling'},{id:'baseline',label:'Service / account baseline'}],items:[{text:'Restrict the stated member regional APIs after canary testing',bin:'ceiling',explain:'An SCP can cap member identities for the reviewed actions/context; management/SLR exemptions remain.'},{text:'Give a workforce group scoped production account access',bin:'grant',explain:'Identity Center/IAM role assignments provide grants, still limited by applicable ceilings.'},{text:'Permit dev bucket creation only under reviewed Mumbai endpoint/location restrictions',bin:'both',explain:'Creation needs a grant and the intended organizational/service-context guard; SCP alone does not grant.'},{text:'Prevent a member role from stopping/deleting the protected trail',bin:'ceiling',explain:'An applicable SCP Deny can limit that member role; it is not universal tamper-proof storage.'},{text:'Vend a new account with the chosen landing-zone baseline',bin:'baseline',explain:'Control Tower Account Factory is account provisioning/baseline workflow, not an IAM grant.'},{text:'Share a supported subnet while preserving owner and consumer permissions',bin:'grant',explain:'RAM makes a supported resource usable; the owner retains ownership and the consuming account grants scoped access.'},{text:'Configure supported organization backup settings and verify jobs/restores separately',bin:'baseline',explain:'Backup policies define supported configuration with distinct inheritance, not an SCP grant/deny path.'}]},
   {type:'fill',title:'✍️ Scoped SCP excerpt — endpoint and audit ceiling',instructions:'Fill three blanks. This excerpt protects trail APIs and the listed regional endpoints; region.json also checks S3LocationConstraint separately. No whole data-residency guarantee.',template:'{\n "Version":"2012-10-17",\n "Statement":[\n  {"Effect":"{0}","Action":["cloudtrail:StopLogging","cloudtrail:DeleteTrail"],"Resource":"*"},\n  {"Effect":"Deny","Action":["ec2:*","rds:*","s3:CreateBucket"],"Resource":"*",\n   "Condition":{"{1}":{"aws:RequestedRegion":"ap-south-1"}}}\n ]\n}\n\naws organizations attach-policy --policy-id p-region01 --target-id {2}',tokens:['Deny','StringNotEquals',SAND,'Allow','StringEquals','arn:aws:iam::aws:policy/AdministratorAccess'],blanks:[{answer:'Deny',explain:'The applicable Deny caps the member request. An Allow would not grant permission or prohibit trail tampering.'},{answer:'StringNotEquals',explain:'Deny endpoints outside Mumbai. StringEquals reverses the condition and can block the intended home endpoint.'},{answer:SAND,explain:'Attach to the intended Sandbox OU ID, not an IAM policy ARN. Parent path and separate location restriction still need review.'}]},
   {type:'triage',title:'🩺 Admin in Mumbai, still AccessDenied',symptom:'Fictional Sandbox role has IAM AdministratorAccess. Mumbai CreateBucket with Mumbai LocationConstraint fails. Root allows; two independent organization configuration mistakes remain.',goal:'Inspect ancestors and actual policy content before widening the IAM grant.',commands:[{cmd:`aws organizations list-parents --child-id ${DEV}`,out:`Parents:[{Id:${SAND},Type:ORGANIZATIONAL_UNIT}]`,clue:false,note:'Confirm the actual account parent, then inspect ancestors; a desired OU label is not current membership.'},{cmd:`aws organizations list-policies-for-target --target-id ${W} --filter SERVICE_CONTROL_POLICY`,out:'IncompleteAllowList:Deny s3:DeleteBucket only; no applicable Allow at Workloads',clue:true,note:'A Deny-only baseline leaves the requested Allow missing at this required ancestor.'},{cmd:'aws organizations describe-policy --policy-id p-region01',out:'TRAINING Content:ScopedRegionalAPIs uses StringEquals aws:RequestedRegion=ap-south-1',clue:true,note:'Deny+Equals blocks the intended home endpoint. Fix the reviewed condition as well as the ancestor Allow.'},{cmd:'cat identity.json',out:'TRAINING role policy already grants s3:CreateBucket/s3:PutObject/cloudtrail:StopLogging',clue:false,note:'Grant does not widen the applicable SCP ceiling. StopLogging should remain denied by the separate audit SCP.'}],questions:[Q('What explains the stated home-region denial despite AdministratorAccess?', 'Workloads lacks an applicable Allow and the regional Deny uses reversed Equals; both need a reviewed repair',['The IAM grant alone must be missing because AdministratorAccess automatically removes all inherited SCP restrictions','The target account FullAWSAccess overrides every ancestor, so the only possible cause is a management-account exemption','The Config delegate must be exempt from SCPs, so registering any member as delegate is the correct access repair'],0,'A path Allow gap and reversed Deny both matter. Admin does not bypass SCP; child Allow cannot widen an ancestor, and service delegation does not exempt a member identity.'),Q('Which change keeps the intended guardrails while restoring correct access?', 'Restore a suitable Workloads Allow, update reviewed NotEquals/location policy and inspect current corrected content',['Detach every SCP from the root and disable all organization policies because lack of ceilings is equivalent to correct governance','Move the production accounts into an unguarded root so the sandbox role can recover access without reviewing policy context','Move dev to a newly named unguarded OU and assume the new label preserves the intended Region/audit protections'],1,'Repair the specific path/condition and preserve intended protections/work. Disabling ceilings or moving production erases the control objective; a new unguarded label does not preserve the intended permission and protection contract.') ]},
   {type:'terminal',title:'🖥️ Build the Sandbox boundary and one service delegate',instructions:'In-app Organizations fixture only. Management caller configures the organization; no real account creation, closure or AWS requests.',goal:'<p><b>1.</b> Create Sandbox under Workloads '+W+'. Fresh first OU ID is '+SAND+'; inspect list-organizational-units-for-parent if needed. Move only dev-sandbox '+DEV+' from Production '+PROD+' to the new Sandbox. Keep the 6 original accounts and Production/Security ownership.</p><p><b>2.</b> Attach reviewed p-region01 and p-notrail1 to Sandbox. Existing FullAWSAccess baseline permits root/everyOU/account paths. Required bounded role contracts:allow Mumbai/Mumbai CreateBucket and existing PutObject;deny EU endpoint, wrong bucket location and StopLogging. IAM grant remains in identity.json; SCP grants nothing.</p><p><b>3.</b> Enable trusted access for '+SERVICE+', register audit '+AUDIT+' as delegate for that exact service, then full list-delegated-administrators filtered by the principal. Expected current registry contains audit. This is Config rules/conformance-pack registration metadata, not aggregator/rules/runtime setup.</p><p>7 actions. Preserve original production DB/order queue/message, policy identities and existing accounts/OUs. Removing guardrails, moving production, broad policy replacements, deleted work, stale/query-filtered registry output or delegation without trusted access cannot qualify. Actual AWS authorization needs an approved canary; Moto does not enforce SCPs.</p>',account:seed(),files,tasks,solution,hints:['Inspect the current tree, region.json, audit.json and identity.json. Move only the intended member and distinguish a grant from a ceiling.',solution.slice(0,2).join(' phir '),solution.slice(2,4).join(' phir '),solution.slice(4).join(' phir ')],success:AG.allOf(tasks),successText:'Original production/accounts/work preserved. Sandbox membership and reviewed effective ceilings match the five role/request contracts; trusted Config integration/audit delegation and current registry read are ready. No actual AWS enforcement, Config rules or landing-zone runtime is claimed.'},
   {type:'docker',title:'🐳 Lab22 — actual org metadata, forbidden request accepted',project:'22-org-scp-guardrails',goal:'Run the owned virtual organization sequence and inspect actual metadata versus the missing enforcement.',why:'Moto accepts registration without trusted access and a forbidden member bucket despite Deny; an attachment is not runtime authorization proof.',steps:[{text:'From aws-gurukul, read README/lab.py and run the exact local script.',cmd:'./docker-labs/.venv/bin/python -I docker-labs/22-org-scp-guardrails/lab.py',expect:'6 behavior checks:virtual org/accounts/nested OU move/default FullAWSAccess/attachment/delegation/member identity/forbidden-region location.'},{text:'Inspect REGISTER WITHOUT TRUSTED ACCESS and MEMBER OUTSIDE_REGION lines.',expect:'Moto accepts both; correct trusted-access path is also replayed. Member eu-west-1bucket exists despite the attached Deny. Local STS identity is not real trust-policy validation.'},{text:'Read cleanup and the State-versus-Status note.',expect:'Membership cleanup 7, scoped cleanup 8, OWNED MOTO STOPPED / LISTENER CLOSED. No real accounts closed; RemoveAccountFromOrganization only removes membership.'}],observe:Q('What does the lab22 result actually support?', 'Local org/tree/attachment/delegation metadata and member identity were verified; SCP enforcement demonstrably diverged',['The attachment proves real AWS authorization because a successful Organizations response evaluates every later member API','The forbidden bucket proves the reviewed SCP grants access because a Deny statement is interpreted as an IAM Allow','Member removal proves real AWS accounts were closed and all charges stopped because organization membership is ownership'],2,'Actual local metadata passed, but the forbidden request was accepted without SCP enforcement. A Deny is not a grant; removing membership does not close a real account or establish billing cleanup.')},
   {type:'quiz',title:'🎓 Governance decisions and current scope',questions:[
    Q('A target account has FullAWSAccess; an ancestor has no applicable Allow. IAM admin requests the action. Result?', 'Denied by the missing ancestor Allow; every root/OU/account path level must permit the member request',['Allowed because the account-local Allow has higher precedence than the root and OU ceilings for an administrator','Allowed because FullAWSAccess is an identity grant that replaces any absent organization policy on the account path','Denied only if the request comes from management because management identities are the only identities affected by SCPs'],0,'Child/identity grants cannot widen a missing ancestor ceiling. FullAWSAccess is not an identity grant; member identities are affected while management identities are exempt.'),
    Q('A Deny applies at the root and a child OU has an Allow for the same action. What follows?', 'The applicable explicit Deny wins for the member identity; a child Allow cannot override the inherited prohibition',['The child Allow wins because organization policies use the same last-file-wins order as a local configuration merge','The account admin can bypass the Deny by attaching AdministratorAccess because identity grants have priority over ceilings','Moving the same role to a delegated-administrator member automatically removes all SCP restrictions on that role'],1,'Applicable explicit Deny wins across the path. No file order or IAM admin grant overrides it; delegated membership remains SCP-bound.'),
    Q('Who is outside SCP restrictions while still requiring appropriate service/IAM authority?', 'Identities in the management account and service-linked roles; delegated member identities generally remain in scope',['Every role with a service name, because ordinary application execution roles and service-linked roles are identical','Every account named audit, because an account display name automatically converts a member into management ownership','Every member root user, because SCPs affect only non-root IAM users and can never limit the member account root'],2,'SCP exceptions are specific. An ordinary service/execution role is not necessarily a service-linked role; names do not change ownership; member root is in SCP scope.'),
    Q('A scoped Region SCP allows the requested endpoint. Does that universally prove all data stays in that Region?', 'No; RequestedRegion controls the request endpoint, and service-specific placement/destination context needs review',['Yes because every AWS API stores all resulting data in the same Region where the signed request endpoint resides','Yes for S3CreateBucket because a supplied LocationConstraint is ignored whenever the endpoint Region is permitted','No only for management identities because member roles can never invoke an API that has a separate destination field'],3,'Endpoint and downstream data placement differ. Review relevant service context such as S3LocationConstraint and other APIs; neither member status nor endpoint permission is a universal residency proof.'),
    Q('Need scoped workforce access across several AWS accounts through one central portal. Candidate?', 'IAM Identity Center organization-instance assignments/permission-set role workflow, with reviewed grants and ceilings',['An SCP Allow by itself because permission ceilings issue employee sessions and create all required account roles','An Identity Center account instance because isolated application instances automatically enable multi-account AWS access','RAM alone because sharing a subnet also provisions a complete workforce identity directory and permission-set assignments'],0,'The organization-instance workforce workflow provides assigned account access; ceilings still apply. SCPs do not grant sessions, account instances have different scope and RAM shares supported resources rather than replacing workforce identity.'),
    Q('A Config delegated administrator is registered. What should the readiness review still check?', 'Exact trusted-access/service integration and required Config runtime setup; registration does not exempt the member from SCPs',['Whether the delegate has become the management account, because every service registration transfers organization ownership','Nothing else because Organizations registration automatically deploys all Config recorders, rules and aggregators everywhere','Only the account name because an audit label grants every supported security service the same delegated capability'],1,'Delegation is service-specific metadata/prerequisites, not complete service deployment or management ownership. Member ceilings remain; labels do not configure other integrations.'),
    Q('Basic tag-policy value/case enforcement is enabled. Missing-tag create prevention needed. Accurate next step?', 'Review Required-key/IaC/reporting coverage and supported request-tag IAM/SCP guards; basic value rules alone do not require absent tags',['Assume basic tag-value enforcement rejects every completely untagged resource across every AWS service automatically','Replace account IAM grants with a tag policy because tag consistency policies provide every required resource permission','Disable resource inventory because compliance reports already contain every resource that has never had any user-defined tag'],2,'Basic rules do not cover absent keys; current Required-key/IaC/reporting features have supported scope/visibility limits. Use documented create/request-tag controls where supported; tag policies are not grants or universal inventory.'),
    Q('The current SCP syntax reference allows Condition/Resource with Allow. An older guide forbids both. Which wins?', 'Use current SCP syntax and tested supported semantics; the 2025expansion added those capabilities, while local simulators may be narrower',['Follow the older rule because an AWS service can never extend an authorization policy language after the first launch','Treat an SCP Allow with a resource as a new IAM grant because flexible syntax removes the distinction between grant and ceiling','Assume every unsupported simulator expression works silently because current AWS capabilities automatically exist in local code'],3,'Current primary syntax/launch docs supersede stale restrictions; syntax expansion does not turn SCP into a grant. A bounded simulator must report unsupported scope rather than silently claim full AWS support.')
   ]}
  ],
  interview:{title:'Interview — isolation, grants and a broken Allow path',instructions:'Four decisions, then repair only the specified ancestor/policy mistakes while preserving the existing Sandbox and service registry.',questions:[
   Q('Separate prod/dev accounts exist, but a shared dev credential can assume broad production roles. Best response?', 'Review and restrict cross-account trust/grants and credential handling; account separation alone is not immunity',['Treat the account boundary as sufficient because credentials can never be authorized across two AWS accounts','Move all resources back into one account because cross-account trust proves that separate accounts provide no isolation benefit','Replace role trust with an SCP Allow because organizational ceilings are the mechanism that issues temporary production sessions'],0,'Accounts isolate, but authorized credentials/trust can cross boundaries. Restrict the actual paths; neither abandoning isolation nor an SCP Allow fixes broad session authority.'),
    Q('A same-account bucket policy grants PutObject to a role ARN; IAM has no Allow, boundary allows and SCP path allows. Decision?', 'That role-ARN resource grant can allow the object request; this differs from creating a bucket without an existing resource policy',['Denied because resource policies can never grant a role permission without a matching identity Allow for the exact same action','Allowed even if the role boundary does not allow the action because every resource grant bypasses all boundary and SCP limits','Allowed to create every new bucket as well because an existing object grant automatically attaches to all future S3 resources'],1,'Same-account role-ARN resource grants are real grants, limited by applicable boundary/ceilings. They do not universally bypass restrictions or authorize future nonexistent buckets; user/session ARN paths have other rules.'),
    Q('Control Tower proactive controls are enabled. A direct Terraform AWS-provider API creates a resource. Can hook evaluation be assumed?', 'No; verify the actual provisioning path and coverage, because proactive controls target supported CloudFormation hook operations',['Yes because managing any Control Tower control through Terraform makes every direct provider API a CloudFormation stack operation','Yes because a detective Config rule always blocks a request synchronously before the target service creates the resource','No only when an SCP grants the action because SCP Allow is the mechanism that disables every CloudFormation hook'],2,'Proactive hooks have specific provisioning coverage. Managing controls with Terraform does not transform direct APIs; Config detection is different from synchronous prevention, and SCP Allow neither grants access nor disables hooks.'),
    Q('RI/Savings Plans discount sharing is configured across accounts. What is accurate?', 'Eligible benefit sharing follows purchasing/account/group preferences; it does not grant IAM access or guarantee running capacity',['Every account receives a fixed extra discount regardless of commitment utilization, sharing preferences and benefit eligibility','A shared discount is also a cross-account role trust grant, so consumers automatically gain access to the purchasing workload','All resource quotas and capacity reservations become one unlimited pool because a consolidated invoice combines authorization and infrastructure'],3,'Billing preferences/eligibility govern benefits, including current group modes. Discounts are not IAM grants, fixed universal savings, unlimited quotas or a guarantee of running capacity.') ,
    {terminal:{type:'terminal',title:'🖥️ Restore ancestor Allow and correct Region condition',instructions:'Original Sandbox, accounts, delegation and production work must remain. Do not disable policy types or replace policy identity.',goal:'<p>Workloads '+W+' has a Deny-only baseline without an applicable Allow; p-region01 has reversed StringEquals. Attach existing p-FullAWSAccess to Workloads, update original p-region01 content from region.json, then full describe-policy. Expected corrected Content plus permitted home CreateBucket/object and denied wrong endpoint/location/StopLogging. Preserve original Sandbox '+SAND+', all accounts/production work, audit delegation/trusted access and p-notrail1.3 actions; current policy revision/read required.</p>',account:seed(true,true),files,tasks:itasks,solution:isolution,hints:['A child/IAM Allow cannot fix an ancestor gap. Deny+Equals also blocks the intended endpoint; repair both independent mistakes.',isolution.slice(0,2).join(' phir '),isolution[2]],success:AG.allOf(itasks),successText:'Original Sandbox/work/registry preserved. Workloads Allow and reviewed Region/location condition restored; current policy content and bounded request outcomes match. Actual AWS enforcement remains a separate approved canary test.'}}
  ]},
  success:['Account/OU design ko trust, ownership and policy scope se explain kar sakta hoon.','SCP path, explicit Deny and stated IAM/resource grant path ka deciding layer identify kar sakta hoon.','Identity Center/Control Tower/RAM/delegation and current policy types choose karke limits verify kar sakta hoon.'],
  homework:'<p>Optional approved isolated organization/member-account canary only. Real account creation, closure, root-wide SCP changes or policy-type disabling need separate explicit approval and recovery/billing planning. Start read-only:inventory root/parents/direct policies, current State and actual grants/context. Review a narrow proposed policy and rollback/exception owner before applying. With approval, verify intended positive/negative AWS requests and service setup, preserving production and audit evidence. Membership removal is not account closure; cleanup only owned test resources and verify continuing charges/retention obligations.</p>',
  cards:[{front:'Account boundary enough?',back:'Strong isolation, not immunity to broad cross-account trust/credentials or shared dependencies. Separate ownership and restrict actual access paths.'},{front:'SCP path rule?',back:'Applicable Allow at root/everyOU/account; multiple policies at one level contribute Allows; any applicable explicit Deny wins. SCP never grants.'},{front:'SCP exceptions?',back:'Management identities and service-linked roles are exempt; delegated member identities and member root are generally in scope. Exemption is not an arbitrary grant.'},{front:'Resource grant versus identity grant?',back:'Same-account role-ARN resource grant can grant object access without identity Allow but is boundary/session limited. Direct user/session/wildcard Principal paths differ; SCP still matters.'},{front:'Region endpoint versus data location?',back:'RequestedRegion is request endpoint. Review service-specific location/destination context, such as S3LocationConstraint; avoid blanket global-service breakage.'},{front:'Identity Center / Account Factory / RAM?',back:'Workforce account/application access; repeatable account baseline; supported resource sharing. Different objectives, grants and prerequisites.'},{front:'Current policy/billing caveats?',back:'SCP 2025 full syntax, RCP/declarative/tag/backup coverage differs. Basic tag rules do not enforce absent tags; current required-key/IaC scope matters. Eligible discount sharing is not authorization/capacity.'},{front:'Lab22 evidence?',back:'Virtual organization/tree/attachments/delegation/identity passed; Moto accepts missing trusted access and forbidden member bucket. No real AWS authorization/account closure or service runtime proof.'}]
 }]);
})();
